def lps(s):
    """
    This function takes a string 's' and returns the length of the longest palindromic subsequence in 's'.
    A palindromic subsequence is a sequence of characters that are the same when read from left to right and from right to left, but the characters do not have to be consecutive.
    """
    def longestPalindrome(sub, i, j):
        # Base Case
        if i > j:
            return 0
        if i == j:
            return 1
        # Recursive Cases
        if s[i] == s[j] and i != j + 1:
            return longestPalindrome(sub, i + 1, j - 1) + 2
        elif s[i] == s[j] and i == j + 1:
            return longestPalindrome(sub, i + 1, j - 1) + 1
        else:
            return max(longestPalindrome(sub, i + 1, j), longestPalindrome(sub, i, j - 1))
    return longestPalindrome(s, 0, len(s) - 1)

